+    it("should return false when default encryption setting is false", () => {
+        mockClient.getClientWellKnown.mockReturnValue({
+            "io.element.e2ee": {
+                force_disable: false,
+                default: false,
+            },
+        });
+        expect(privateShouldBeEncrypted(mockClient)).toEqual(false);
