+	}))
+	defer ts.Close()
+
+	r := &models.ScanResult{
+		Family:  constant.Oracle,
+		Release: "7Server",
+		Packages: models.Packages{
+			"nginx": models.Package{
+				Name:    "nginx",
+				Version: "2.17",
+				Release: "105.0.1",
+				Arch:    "x86_64",
+			},
+		},
+	}
+
+	relatedDefs, err := getDefsByPackNameViaHTTP(r, ts.URL)
+
+	// Requirement: non-nil error must be returned when arch is missing for Oracle
+	if err == nil {
+		t.Fatal("getDefsByPackNameViaHTTP: expected non-nil error when arch is empty for Oracle, got nil")
+	}
+	// Requirement: caller wraps the error as "Failed to detect OVAL"
+	if !strings.Contains(err.Error(), "Failed to detect OVAL") {
+		t.Errorf("getDefsByPackNameViaHTTP: expected error containing %q, got: %s",
+			"Failed to detect OVAL", err.Error())
+	}
+	// Requirement: the errored definition must NOT be added to relatedDefs (skipped)
+	if len(relatedDefs.entries) != 0 {
+		t.Errorf("getDefsByPackNameViaHTTP: expected empty relatedDefs on arch error, got %d entries",
+			len(relatedDefs.entries))
+	}
+}

